package com.stocksentinel.chips;
import org.apache.ibatis.annotations.*;import java.time.*;import java.util.*;import java.math.BigDecimal;
import com.stocksentinel.common.entity.StockInfo;
import com.stocksentinel.notification.NotificationRow;
@Mapper
public interface ChipMapper {
    class Run {public LocalDate tradeDate;public String parameters,status;public boolean paused;}
    @Select("SELECT trade_date,parameters::text,status,COALESCE(retry_after>now(),false) AS paused FROM chip_scan_run WHERE trade_date=#{date}")Run run(LocalDate date);
    @Insert("INSERT INTO chip_scan_run(trade_date,parameters) VALUES(#{date},CAST(#{parameters} AS jsonb)) ON CONFLICT DO NOTHING")int start(@Param("date")LocalDate date,@Param("parameters")String parameters);
    @Insert("INSERT INTO chip_scan_item(trade_date,symbol) SELECT #{date},symbol FROM stock_info WHERE status='ACTIVE' AND exchange IN ('SH','SZ') ON CONFLICT DO NOTHING")int seed(LocalDate date);
    @Select("SELECT s.* FROM chip_scan_item i JOIN stock_info s USING(symbol) WHERE trade_date=#{date} AND(i.status='PENDING' OR i.status='FAILED' AND attempts<3 AND next_retry_at<=now()) ORDER BY EXISTS(SELECT 1 FROM personal_position p WHERE p.symbol=s.symbol AND quantity>0) DESC,EXISTS(SELECT 1 FROM stock_watchlist w WHERE w.symbol=s.symbol AND enabled) DESC,s.symbol LIMIT 20")List<StockInfo> pending(LocalDate date);
    @Update("UPDATE chip_scan_item SET status=#{status},code=#{code},snapshot=CAST(#{snapshot} AS jsonb),concentration90=#{c90},concentration70=#{c70},average_amount=#{amount},attempts=attempts+1,last_attempt_at=now(),last_success_at=CASE WHEN #{status} IN ('MATCHED','NO_MATCH') THEN now() ELSE last_success_at END,next_retry_at=now()+interval '15 minutes' WHERE trade_date=#{date} AND symbol=#{symbol}")int item(@Param("date")LocalDate date,@Param("symbol")String symbol,@Param("status")String status,@Param("code")String code,@Param("snapshot")String snapshot,@Param("c90")BigDecimal c90,@Param("c70")BigDecimal c70,@Param("amount")BigDecimal amount);
    @Select("SELECT status,code,count(*) AS count FROM chip_scan_item WHERE trade_date=#{date} GROUP BY status,code ORDER BY status,code")List<Map<String,Object>> coverage(LocalDate date);
    @Select("SELECT count(*) FROM chip_scan_item WHERE trade_date=#{date} AND(status='PENDING' OR status='FAILED' AND attempts<3)")int unfinished(LocalDate date);
    @Select("SELECT i.symbol,s.name,i.concentration90,i.concentration70,i.average_amount,i.snapshot::text AS snapshot FROM chip_scan_item i JOIN stock_info s USING(symbol) WHERE trade_date=#{date} AND i.status='MATCHED' ORDER BY concentration90,concentration70,average_amount DESC,i.symbol LIMIT 5")List<Map<String,Object>> candidates(LocalDate date);
    @Select("SELECT i.symbol,s.name,i.status,i.code,i.attempts,i.last_attempt_at,i.last_success_at,i.snapshot::text AS snapshot FROM chip_scan_item i JOIN stock_info s USING(symbol) WHERE trade_date=#{date} ORDER BY i.symbol LIMIT #{limit} OFFSET #{offset}")List<Map<String,Object>> items(@Param("date")LocalDate date,@Param("limit")int limit,@Param("offset")int offset);
    @Update("UPDATE chip_scan_run SET retry_after=now()+interval '15 minutes',last_error=#{code} WHERE trade_date=#{date}")int pause(@Param("date")LocalDate date,@Param("code")String code);
    @Update("UPDATE chip_scan_run SET status=#{status},retry_after=NULL,finished_at=now() WHERE trade_date=#{date} AND status='RUNNING'")int finish(@Param("date")LocalDate date,@Param("status")String status);
    @Insert("INSERT INTO notify_record(channel,message_type,idempotency_key,target_chat_id,payload) VALUES('WECOM_SMART_BOT','CHIP_CANDIDATE',#{key},#{chat},#{text}) ON CONFLICT DO NOTHING")int notice(@Param("key")String key,@Param("chat")String chat,@Param("text")String text);
    @Update("UPDATE notify_record SET status='UNKNOWN',last_error='LEASE_EXPIRED',claim_token=NULL WHERE message_type='CHIP_CANDIDATE' AND status='SENDING' AND lease_until<now()")int expire();
    @Update("UPDATE notify_record SET status='EXPIRED',last_error='CHIP_NOTICE_STALE' WHERE message_type='CHIP_CANDIDATE' AND status IN ('PENDING','RETRY') AND created_at<now()-interval '8 hours'")int expirePending();
    @Select(value="WITH c AS(SELECT id FROM notify_record WHERE message_type='CHIP_CANDIDATE' AND target_chat_id=#{chat} AND status IN ('PENDING','RETRY') AND attempts<3 AND(next_retry_at IS NULL OR next_retry_at<=now()) ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE notify_record n SET status='SENDING',attempts=attempts+1,claim_token=#{token},lease_until=now()+interval '120 seconds' FROM c WHERE n.id=c.id RETURNING n.*",affectData=true)@Options(flushCache=Options.FlushCachePolicy.TRUE,useCache=false)NotificationRow claim(@Param("chat")String chat,@Param("token")String token);
    @Update("UPDATE notify_record SET status=#{status},last_error=#{code},sent_at=CASE WHEN #{status}='SUCCESS' THEN now() ELSE sent_at END,next_retry_at=CASE WHEN #{status}='RETRY' THEN now()+interval '60 seconds' ELSE NULL END,claim_token=NULL WHERE message_type='CHIP_CANDIDATE' AND id=#{id} AND claim_token=#{token} AND status='SENDING'")int delivered(@Param("id")long id,@Param("token")String token,@Param("status")String status,@Param("code")String code);
}
